controls.onClick:
{() => {
              setSubmitted(true);
              if (canOrder) onOrder({ size: requestedSize, color: color.trim(), option: selectedOption, quantity, customerNote: customerNote.trim(), manualUrl: manualUrl.trim() });
            }}

controls.className:
{`flex h-11 w-11 shrink-0 items-center justify-center rounded-control transition active:scale-90 disabled:pointer-events-none disabled:opacity-35 ${
                isRecording
                  ? 'animate-pulse bg-danger text-white'
                  : surfaceButton
              }`}

{`flex h-11 w-11 shrink-0 items-center justify-center rounded-control border border-line bg-white text-ink shadow-sm transition hover:bg-surface active:scale-90 disabled:pointer-events-none disabled:opacity-35 ${
                  voiceMode ? 'ring-2 ring-white animate-pulse' : ''
                }`}

controls.onClick:
{() => {
                  if (!available) {
                    setPaymentAvailabilityNotice(method === 'FLOUCI'
                      ? tr('Flouci / D17 reste visible mais désactivé : aucune transaction ne sera simulée sans passerelle réelle.', 'Flouci / D17 ظاهرة لكنها معطلة: لن يتم إنشاء دفع وهمي دون بوابة حقيقية.')
                      : tr('Ce moyen sera activé dès que sa configuration officielle sera disponible.', 'ستُفعّل هذه الوسيلة عند توفر إعداداتها الرسمية.'));
                    return;
                  }
                  setPaymentAvailabilityNotice(''); setError(null);
                  setFormData({ ...formData, paymentMethod: method.toLowerCase() });
                }}

{() => {
                setEmailMode(emailMode === 'login' ? 'register' : 'login');
                setEmailAddress(''); setEmailName('');
                setEmailPassword(''); setShowPassword(false); setRecoveryOpen(false); setError(''); setNotice('');
                document.getElementById('auth-title')?.focus();
              }}

